#!/usr/bin/env node
/**
 * plank-join.mjs — Shipshape plank-join checker.
 *
 * Scans implementation directories for @planks and @planks-provisional annotations.
 * Joins them against current step-definition patterns and @captain scenarios.
 * Exits non-zero where:
 *   - a behaviour-bearing seam has no plank
 *   - a @planks string matches no current step-definition pattern
 *   - a @planks-provisional reference names a scenario that lost its @captain tag
 *
 * Usage: node .shipshape/plank-join.mjs
 */

import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();

// --- Read RIGGING.md to find implementation and specs dirs ---
function readRigging() {
  const rigPath = path.join(ROOT, 'RIGGING.md');
  if (!fs.existsSync(rigPath)) return { implementation: ['.'], specs: ['features'] };
  const txt = fs.readFileSync(rigPath, 'utf8');
  const extract = (key) => {
    const lines = [];
    let inSection = false;
    for (const line of txt.split('\n')) {
      if (line.startsWith('## ')) inSection = false;
      if (line === `## ${key}` || (key === 'Directories' && line.startsWith('## '))) {
        if (key === 'Directories') inSection = line === '## Directories';
        continue;
      }
      if (inSection || (key === 'Directories' && line.match(/^- \w+: /))) {
        const m = line.match(/^- \w+: (.+)$/);
        if (m) lines.push(m[1].trim());
      }
    }
    return lines;
  };

  // Simpler: just grep for values under sections
  const lines = txt.split('\n');
  let section = '';
  const result = { implementation: [], specs: [], verification: [] };
  for (const line of lines) {
    const secMatch = line.match(/^## (\w+)/);
    if (secMatch) { section = secMatch[1]; continue; }
    const kvMatch = line.match(/^- (\w+): (.+)$/);
    if (kvMatch && section === 'Directories') {
      const [, k, v] = kvMatch;
      if (k === 'implementation' || k === 'specs' || k === 'verification') {
        result[k].push(v.trim());
      }
    }
  }
  if (result.implementation.length === 0) result.implementation = ['.'];
  if (result.specs.length === 0) result.specs = ['features'];
  return result;
}

// --- Collect files matching extensions ---
function collectFiles(dirs, exts) {
  const files = [];
  for (const d of dirs) {
    const abs = path.resolve(ROOT, d);
    if (!fs.existsSync(abs)) continue;
    walk(abs, exts, files);
  }
  return files;
}

function walk(dir, exts, acc) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === '.shipshape') continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, exts, acc);
    else if (exts.some(e => entry.name.endsWith(e))) acc.push(full);
  }
}

// --- Extract step-definition patterns from step files ---
function extractPatterns(stepFiles) {
  const patterns = new Set();
  // Match: Given("...", ...), When("...", ...), Then("...", ...), etc.
  const patRe = /^(Given|When|Then)\s*\(\s*["'`]([^"'`]+)["'`]/gm;
  for (const f of stepFiles) {
    const txt = fs.readFileSync(f, 'utf8');
    let m;
    while ((m = patRe.exec(txt))) {
      patterns.add(m[2]);
    }
  }
  return patterns;
}

// --- Extract @captain scenarios from feature files ---
function extractCaptainScenarios(featureFiles) {
  const scenarios = new Set();
  for (const f of featureFiles) {
    const txt = fs.readFileSync(f, 'utf8');
    const lines = txt.split('\n');
    let inScenario = false;
    let scenarioName = '';
    let hasCaptain = false;
    for (const line of lines) {
      const scenMatch = line.match(/^\s*Scenario:\s+(.+)/);
      if (scenMatch) {
        // Save previous if it was @captain
        if (inScenario && hasCaptain) {
          const rel = path.relative(ROOT, f);
          scenarios.add(`${rel}:${scenarioName}`);
        }
        inScenario = true;
        scenarioName = scenMatch[1].trim();
        hasCaptain = false;
      }
      if (inScenario && line.includes('@captain')) {
        hasCaptain = true;
      }
      if (inScenario && line.match(/^\s*$/) && !line.match(/^\s*Scenario/)) {
        // blank line could end scenario
      }
    }
    // Last scenario
    if (inScenario && hasCaptain) {
      const rel = path.relative(ROOT, f);
      scenarios.add(`${rel}:${scenarioName}`);
    }
  }
  return scenarios;
}

// --- Extract planks from production files ---
function extractPlanks(prodFiles) {
  const planks = [];
  // Match @planks("...") and @planks-provisional("...")
  const plankRe = /@planks\s*\(\s*["'`]([^"'`]+)["'`]\s*\)/g;
  const provRe = /@planks-provisional\s*\(\s*["'`]([^"'`]+)["'`]\s*\)/g;
  for (const f of prodFiles) {
    const txt = fs.readFileSync(f, 'utf8');
    let m;
    while ((m = plankRe.exec(txt))) {
      planks.push({ file: f, type: 'planks', value: m[1], line: txt.slice(0, m.index).split('\n').length });
    }
    while ((m = provRe.exec(txt))) {
      planks.push({ file: f, type: 'planks-provisional', value: m[1], line: txt.slice(0, m.index).split('\n').length });
    }
  }
  return planks;
}

// --- Also scan for bare @planks tokens outside docblocks (malformed planks) ---
function extractBareTokens(prodFiles) {
  const bare = [];
  for (const f of prodFiles) {
    const txt = fs.readFileSync(f, 'utf8');
    const lines = txt.split('\n');
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      if (line.match(/@planks/) && !line.match(/@planks(-provisional)?\s*\(/)) {
        bare.push({ file: f, line: i + 1, text: line.trim() });
      }
    }
  }
  return bare;
}

// --- Main ---
const dirs = readRigging();
const prodFiles = collectFiles(dirs.implementation, ['.js', '.mjs', '.ts', '.jsx', '.tsx']);
const stepFiles = collectFiles(dirs.verification, ['.js', '.mjs', '.ts']);
const featureFiles = collectFiles(dirs.specs, ['.feature']);

const patterns = extractPatterns(stepFiles);
const captainScenarios = extractCaptainScenarios(featureFiles);
const planks = extractPlanks(prodFiles);
const bareTokens = extractBareTokens(prodFiles);

let exitCode = 0;
const errors = [];

// Check 1: every @planks matches a current pattern
for (const p of planks) {
  if (p.type === 'planks' && !patterns.has(p.value)) {
    errors.push(`STALE_PLANK: ${path.relative(ROOT, p.file)}:${p.line} — @planks("${p.value}") matches no step-definition pattern`);
    exitCode = 1;
  }
}

// Check 2: every @planks-provisional names a scenario still carrying @captain
for (const p of planks) {
  if (p.type === 'planks-provisional') {
    if (!captainScenarios.has(p.value)) {
      errors.push(`ORPHAN_PROVISIONAL: ${path.relative(ROOT, p.file)}:${p.line} — @planks-provisional("${p.value}") — scenario not found or missing @captain`);
      exitCode = 1;
    }
  }
}

// Check 3: bare @planks tokens outside docblocks
for (const b of bareTokens) {
  errors.push(`MALFORMED_PLANK: ${path.relative(ROOT, b.file)}:${b.line} — bare @planks token: ${b.text}`);
  exitCode = 1;
}

// Check 4: every behaviour-bearing step-definition pattern has at least one plank
// (This is the plank-coverage rule. We only check patterns that exist.)
for (const pattern of patterns) {
  const found = planks.some(p => p.type === 'planks' && p.value === pattern);
  if (!found) {
    errors.push(`UNPLANKED_PATTERN: step definition pattern "${pattern}" has no matching @planks annotation`);
    exitCode = 1;
  }
}

// Report
if (errors.length === 0) {
  console.log('plank-join: OK — all planks join, no orphans, no malformation');
} else {
  for (const e of errors) console.error(e);
}

process.exit(exitCode);

#!/usr/bin/env node
/**
 * verification-conformance.mjs — Verification-conformance rule set.
 *
 * Checks methodology violations that the plank-join checker cannot reach:
 *   1. plank-form: every @planks / @planks-provisional is a docblock tag on a declaration,
 *      every @planks string is a current step-definition pattern, every @planks-provisional
 *      names a scenario still carrying @captain.
 *   2. plank-coverage: every behaviour-bearing step-definition pattern has a matching plank.
 *   3. forbidden-doubles: no @exceptional-double outside a step-definition or support file.
 *   4. perturbation-quiescence: no standing PERTURBATION token in implementation when tree is green.
 *
 * Usage: node .shipshape/verification-conformance.mjs [--plant-<violation>]
 *
 * Flags:
 *   --plant-plank-form         plant a malformed plank (line comment, not docblock)
 *   --plant-plank-coverage     plant an unplanked step definition
 *   --plant-forbidden-double   plant a test double outside verification support
 *   --plant-perturbation       plant a standing PERTURBATION token
 *   --check                    run all checks (default, no flag)
 *   --remove-plant             remove the planted violation (leaves green)
 */

import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();

// --- Helpers ---
function readRigging() {
  const rigPath = path.join(ROOT, 'RIGGING.md');
  const txt = fs.existsSync(rigPath) ? fs.readFileSync(rigPath, 'utf8') : '';
  const lines = txt.split('\n');
  let section = '';
  const result = { implementation: [], specs: [], verification: [], perturb: '' };
  for (const line of lines) {
    const secMatch = line.match(/^## (\w+)/);
    if (secMatch) { section = secMatch[1]; continue; }
    const kvMatch = line.match(/^- (\w+): `(.+)`$/);
    if (kvMatch) {
      const [, k, v] = kvMatch;
      if (section === 'Directories' && (k === 'implementation' || k === 'specs' || k === 'verification')) {
        result[k].push(v.trim());
      }
      if (section === 'Perturbation' && k === 'perturb') {
        result.perturb = v.trim();
      }
    }
    // Also match non-backtick values
    const kvMatch2 = line.match(/^- (\w+): (.+)$/);
    if (kvMatch2 && !kvMatch) {
      const [, k, v] = kvMatch2;
      if (section === 'Perturbation' && k === 'message') {
        result.perturbMessage = v.trim();
      }
    }
  }
  if (result.implementation.length === 0) result.implementation = ['.'];
  if (result.specs.length === 0) result.specs = ['features'];
  if (result.verification.length === 0) result.verification = ['features/support'];
  return result;
}

function collectFiles(dirs, exts) {
  const files = [];
  for (const d of dirs) {
    const abs = path.resolve(ROOT, d);
    if (!fs.existsSync(abs)) continue;
    walk(abs, exts, files);
  }
  return files;
}

function walk(dir, exts, acc) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === '.shipshape') continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, exts, acc);
    else if (exts.some(e => entry.name.endsWith(e))) acc.push(full);
  }
}

function extractPatterns(stepFiles) {
  const patterns = new Set();
  const patRe = /^(Given|When|Then)\s*\(\s*["'`]([^"'`]+)["'`]/gm;
  for (const f of stepFiles) {
    const txt = fs.readFileSync(f, 'utf8');
    let m;
    while ((m = patRe.exec(txt))) patterns.add(m[2]);
  }
  return patterns;
}

function extractCaptainScenarios(featureFiles) {
  const scenarios = new Set();
  for (const f of featureFiles) {
    const txt = fs.readFileSync(f, 'utf8');
    const lines = txt.split('\n');
    let inScenario = false, scenarioName = '', hasCaptain = false;
    for (const line of lines) {
      const scenMatch = line.match(/^\s*Scenario:\s+(.+)/);
      if (scenMatch) {
        if (inScenario && hasCaptain) scenarios.add(`${path.relative(ROOT, f)}:${scenarioName}`);
        inScenario = true; scenarioName = scenMatch[1].trim(); hasCaptain = false;
      }
      if (inScenario && line.includes('@captain')) hasCaptain = true;
    }
    if (inScenario && hasCaptain) scenarios.add(`${path.relative(ROOT, f)}:${scenarioName}`);
  }
  return scenarios;
}

function extractPlanks(prodFiles) {
  const planks = [];
  const plankRe = /@planks\s*\(\s*["'`]([^"'`]+)["'`]\s*\)/g;
  const provRe = /@planks-provisional\s*\(\s*["'`]([^"'`]+)["'`]\s*\)/g;
  for (const f of prodFiles) {
    const txt = fs.readFileSync(f, 'utf8');
    let m;
    while ((m = plankRe.exec(txt))) planks.push({ file: f, type: 'planks', value: m[1], line: txt.slice(0, m.index).split('\n').length });
    while ((m = provRe.exec(txt))) planks.push({ file: f, type: 'planks-provisional', value: m[1], line: txt.slice(0, m.index).split('\n').length });
  }
  return planks;
}

// --- Plant / remove functions ---
function plantPlankForm() {
  const target = path.join(ROOT, '.shipshape', '_plant_plank_form.js');
  fs.writeFileSync(target, '// @planks("malformed line-comment plank — no docblock")\nmodule.exports = {};\n');
  console.log('PLANTED: malformed plank (line comment, not docblock) at .shipshape/_plant_plank_form.js');
}

function removePlantPlankForm() {
  const target = path.join(ROOT, '.shipshape', '_plant_plank_form.js');
  if (fs.existsSync(target)) fs.unlinkSync(target);
}

function plantPlankCoverage() {
  // Plant a step definition with a pattern that has no matching plank
  const target = path.join(ROOT, '.shipshape', '_plant_step.js');
  fs.writeFileSync(target, `const { Given } = require('@cucumber/cucumber');
Given('an unplanked step definition exists', function () {});
module.exports = {};\n`);
  console.log('PLANTED: unplanked step definition at .shipshape/_plant_step.js');
}

function removePlantPlankCoverage() {
  const target = path.join(ROOT, '.shipshape', '_plant_step.js');
  if (fs.existsSync(target)) fs.unlinkSync(target);
}

function plantForbiddenDouble() {
  const target = path.join(ROOT, '.shipshape', '_plant_double.js');
  fs.writeFileSync(target, '// @exceptional-double — forbidden: not in verification support\nmodule.exports = {};\n');
  console.log('PLANTED: forbidden double (outside verification support) at .shipshape/_plant_double.js');
}

function removePlantForbiddenDouble() {
  const target = path.join(ROOT, '.shipshape', '_plant_double.js');
  if (fs.existsSync(target)) fs.unlinkSync(target);
}

function plantPerturbation() {
  const target = path.join(ROOT, '.shipshape', '_plant_perturbation.js');
  fs.writeFileSync(target, 'throw new Error("PERTURBATION: consider current durable context; remove when fixed");\n');
  console.log('PLANTED: standing PERTURBATION token at .shipshape/_plant_perturbation.js');
}

function removePlantPerturbation() {
  const target = path.join(ROOT, '.shipshape', '_plant_perturbation.js');
  if (fs.existsSync(target)) fs.unlinkSync(target);
}

// --- Main checks ---
function runChecks() {
  const dirs = readRigging();
  const prodFiles = collectFiles(dirs.implementation, ['.js', '.mjs', '.ts', '.jsx', '.tsx']);
  const stepFiles = collectFiles(dirs.verification, ['.js', '.mjs', '.ts']);
  const featureFiles = collectFiles(dirs.specs, ['.feature']);

  const patterns = extractPatterns(stepFiles);
  const captainScenarios = extractCaptainScenarios(featureFiles);
  const planks = extractPlanks(prodFiles);

  let exitCode = 0;
  const errors = [];

  // Check 1: plank-form — every @planks is inside a docblock (/** ... */) preceding a declaration
  for (const p of planks) {
    const txt = fs.readFileSync(p.file, 'utf8');
    const lines = txt.split('\n');
    const plankLine = p.line - 1; // 0-indexed
    // Look backwards for docblock start
    let inDocblock = false;
    for (let i = plankLine; i >= 0; i--) {
      const line = lines[i];
      if (line.includes('*/')) inDocblock = true;
      if (line.includes('/**')) { inDocblock = true; break; }
      if (line.match(/^\s*(export|const|let|var|function|class|module)/)) break;
      if (line.match(/^\s*$/)) break;
    }
    // For a line-comment plank (// @planks) or a bare token, inDocblock won't be true
    // We check if the plank line itself looks like a docblock comment
    const plankLineText = lines[plankLine] || '';
    if (!plankLineText.match(/^\s*\/\*\*/) && p.type === 'planks') {
      // Not in a docblock — could be line comment or bare
      if (plankLineText.match(/^\s*\/\//)) {
        errors.push(`PLANK_FORM: ${path.relative(ROOT, p.file)}:${p.line} — @planks in line comment, not docblock`);
        exitCode = 1;
      }
    }
    // Check pattern validity
    if (p.type === 'planks' && !patterns.has(p.value)) {
      errors.push(`PLANK_FORM: ${path.relative(ROOT, p.file)}:${p.line} — @planks("${p.value}") matches no current step-definition pattern`);
      exitCode = 1;
    }
    // Check provisional reference
    if (p.type === 'planks-provisional' && !captainScenarios.has(p.value)) {
      errors.push(`PLANK_FORM: ${path.relative(ROOT, p.file)}:${p.line} — @planks-provisional("${p.value}") — scenario not found or missing @captain`);
      exitCode = 1;
    }
  }

  // Check 2: plank-coverage — every behaviour-bearing step has a plank
  for (const pattern of patterns) {
    const found = planks.some(p => p.type === 'planks' && p.value === pattern);
    if (!found) {
      errors.push(`PLANK_COVERAGE: step pattern "${pattern}" has no matching @planks annotation`);
      exitCode = 1;
    }
  }

  // Check 3: forbidden-doubles — @exceptional-double only in verification support
  for (const f of prodFiles) {
    const isVerification = dirs.verification.some(v => f.startsWith(path.resolve(ROOT, v)));
    if (isVerification) continue;
    const txt = fs.readFileSync(f, 'utf8');
    if (txt.includes('@exceptional-double')) {
      errors.push(`FORBIDDEN_DOUBLE: ${path.relative(ROOT, f)} — @exceptional-double outside verification support`);
      exitCode = 1;
    }
  }

  // Check 4: perturbation-quiescence — no PERTURBATION token in implementation when tree is green
  for (const f of prodFiles) {
    const txt = fs.readFileSync(f, 'utf8');
    if (txt.includes('PERTURBATION')) {
      errors.push(`PERTURBATION_QUIESCENCE: ${path.relative(ROOT, f)} — standing PERTURBATION token in implementation`);
      exitCode = 1;
    }
  }

  // Report
  if (errors.length === 0) {
    console.log('verification-conformance: OK — all methodology checks pass');
  } else {
    for (const e of errors) console.error(e);
  }
  process.exit(exitCode);
}

// --- CLI ---
const args = process.argv.slice(2);

if (args.includes('--remove-plant')) {
  removePlantPlankForm();
  removePlantPlankCoverage();
  removePlantForbiddenDouble();
  removePlantPerturbation();
  console.log('Removed all planted violations');
  process.exit(0);
}

if (args.includes('--plant-plank-form')) plantPlankForm();
if (args.includes('--plant-plank-coverage')) plantPlankCoverage();
if (args.includes('--plant-forbidden-double')) plantForbiddenDouble();
if (args.includes('--plant-perturbation')) plantPerturbation();

if (args.includes('--plant-plank-form') || args.includes('--plant-plank-coverage') ||
